describe("doctests of sympy.core.traversal", () => {
  // a callback parameter outside its callback
  //   use(f, expand, level=2)
  //   => x*(x**2 + 2*x*y + y**2) + 1
  it.todo("use(f, expand, level=2)");
  it("expand(f)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(expand(add(1, mul(x, pow(add(x, y), 2))), {}))).toBe('x**3 + 2*x**2*y + x*y**2 + 1');
  });
});

